from pathlib import Path
import json,hashlib,re
from datetime import datetime
from concurrent.futures import ThreadPoolExecutor,as_completed
import requests
from bs4 import BeautifulSoup
ROOT=Path.cwd();OUT=ROOT/'reports/research/510300_equity_supply_constraint_source_qualification_v1'
assert not (OUT/'source_receipts.json').exists() and not (OUT/'source_acquisition_started.json').exists(),'本来源获取已有记录，不能重启。'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def save(name,d):(OUT/name).write_text(json.dumps(d,ensure_ascii=False,indent=2,allow_nan=False)+'\n',encoding='utf-8')
protocol=json.loads((OUT/'protocol.json').read_text(encoding='utf-8'))
save('source_acquisition_started.json',{'at':datetime.now().astimezone().isoformat(),'fixed_sources':len(protocol['fixed_source_route'])})
def fetch(spec):
 attempts=[]
 for attempt in range(1,3):
  try:
   response=requests.get(spec['url'],timeout=(10,20),headers={'User-Agent':'Mozilla/5.0'})
   attempts.append({'attempt':attempt,'at':datetime.now().astimezone().isoformat(),'http_status':response.status_code})
   if response.status_code in [403,429]:
    return {**spec,'status':'SOURCE_ACCESS_REJECTED','attempts':attempts}
   response.raise_for_status()
   raw=response.content;soup=BeautifulSoup(raw,'html.parser');text=soup.get_text(' ',strip=True)
   title=soup.title.get_text(' ',strip=True) if soup.title else ''
   compact=re.sub(r'\s+','',text)
   missing=[c for c in spec['checks'] if re.sub(r'\s+','',c) not in compact]
   assert len(raw)>1000 and not missing,{'bytes':len(raw),'missing':missing,'title':title}
   path=OUT/'sources'/(spec['id']+'.html');path.write_bytes(raw)
   path.with_suffix('.txt').write_text(text,encoding='utf-8')
   return {**spec,'status':'OFFICIAL_CONTENT_CHECKED','title':title,'source_path':path.relative_to(ROOT).as_posix(),
    'source_sha256':sha(path),'source_bytes':len(raw),'retrieved_at':datetime.now().astimezone().isoformat(),
    'published_at_upper_bound':spec['date']+'T23:59:59+08:00' if spec['date'] else None,
    'historical_first_vintage_verified':False,'attempts':attempts,
    'page_time_meta':[{ 'name':m.get('name',m.get('property','')),'content':m.get('content','')} for m in soup.find_all('meta') if any(k in str(m.get('name',m.get('property',''))).lower() for k in ['time','date','publish'])]}
  except Exception as error:
   attempts.append({'attempt':attempt,'at':datetime.now().astimezone().isoformat(),'error':str(error)[:600],'error_class':type(error).__name__})
 return {**spec,'status':'SOURCE_NOT_ADMITTED','attempts':attempts}
results=[]
with ThreadPoolExecutor(max_workers=3) as pool:
 futures={pool.submit(fetch,s):s['id'] for s in protocol['fixed_source_route']}
 for future in as_completed(futures):
  result=future.result();results.append(result);print(result['id']+'：'+result['status'],flush=True)
receipts=sorted(results,key=lambda v:next(i for i,s in enumerate(protocol['fixed_source_route']) if s['id']==v['id']))
save('source_receipts.json',{'completed_at':datetime.now().astimezone().isoformat(),'items':receipts,
 'fixed_route_size':len(receipts),'admitted':sum(r['status']=='OFFICIAL_CONTENT_CHECKED' for r in receipts),
 'no_unbounded_acquisition':True,'new_market_downloads':0})
print('官方原文获取结束：'+str(sum(r['status']=='OFFICIAL_CONTENT_CHECKED' for r in receipts))+'/'+str(len(receipts)),flush=True)
